@Component({
  selector: 'app-root',
  standalone: true,
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  // Raw input value (for displaying in the header / status text)
  query = '';

  // Results, loading and error state used in the template
  results: Result[] = [];
  isLoading = false;
  error: string | null = null;

  // Stream of search terms coming from the input
  private searchTerm$ = new Subject();

  // Used to clean up the subscription
  private destroy$ = new Subject();

  constructor() {
    // TODO: Wire up the debounced search stream here
    // - debounceTime(500)
    // - distinctUntilChanged()
    // - handle empty queries by clearing results & skipping API
    // - toggle isLoading and error state
    // - switchMap into fakeApiSearch
    // - catch errors and recover with []
    this.setupSearchStream();
  }

  // Called from the template on every input event
  onQueryChange(value: string): void {
    this.query = value;
    // TODO: push the latest value into the searchTerm$ stream
    // this.searchTerm$.next(value);
  }

  ngOnDestroy(): void {
    this.destroy$.next(null);
    this.destroy$.complete();
  }

  private setupSearchStream(): void {
    // TODO: Build the RxJS pipeline here using searchTerm$
    // Example operators: debounceTime, distinctUntilChanged, tap, switchMap, catchError, takeUntil
  }

  // Fake API: filters the in-memory array and responds after a delay.
  // You can treat this as given and focus on the RxJS wiring.
  private fakeApiSearch(term: string) {
    const trimmed = term.trim().toLowerCase();
    const delayMs = 600;

    if (!trimmed) {
      return of([]).pipe(delay(delayMs));
    }

    const filtered = FAKE_DATA.filter((item) => {
      const name = item.name.toLowerCase();
      const email = item.email.toLowerCase();
      return name.includes(trimmed) || email.includes(trimmed);
    });

    // Deliberately fail for the query "error" so students can see error handling.
    if (trimmed === 'error') {
      return timer(delayMs).pipe(
        switchMap(() => throwError(() => new Error('Fake API error')))
      );
    }

    return of(filtered).pipe(delay(delayMs));
  }
}

