:root {
  color-scheme: dark;
}

html,body {
  margin: 0;
  height: 100%;
  background: #0a0a0a;
}

body {
  font-family: system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;
}

.page {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
  background: #0a0a0a;
  color: #e5e7eb;
}

.card {
  width: 100%;
  max-width: 640px;
  background: #0b1020;
  border: 1px solid #1f2937;
  border-radius: 14px;
  padding: 18px;
  display: grid;
  gap: 12px;
}

h1 {
  margin: 0;
  font-size: 20px;
}

.subtitle {
  margin: 0;
  color: #9ca3af;
  font-size: 14px;
  line-height: 1.45;
}

.combobox {
  position: relative;
}

.chip-input {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  padding: 10px;
  border-radius: 12px;
  border: 1px solid #374151;
  background: #0a0f1e;
}

.chip-input:focus-within {
  border-color: #a3e635;
  box-shadow: 0 0 0 2px rgba(163,230,53,.15);
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 4px 10px;
  border-radius: 999px;
  background: #172036;
  border: 1px solid #2c3c62;
  font-size: 13px;
}

.chip-remove {
  border: none;
  background: transparent;
  color: #9ca3af;
  cursor: pointer;
  font-size: 16px;
  line-height: 1;
  padding: 0;
}

.chip-remove:hover {
  color: #e5e7eb;
}

.chip-input input {
  flex: 1;
  min-width: 180px;
  border: none;
  outline: none;
  background: transparent;
  color: #e5e7eb;
  font-size: 14px;
  padding: 4px 0;
}

.chip-input input::placeholder {
  color: #6b7280;
}

.suggestions {
  position: absolute;
  left: 0;
  right: 0;
  z-index: 10;
  margin-top: 8px;
  max-height: 260px;
  overflow: auto;
  border-radius: 12px;
  border: 1px solid #1f2937;
  background: #0a0f1e;
  padding: 0;
  list-style: none;
}

.suggestion {
  display: grid;
  gap: 2px;
  padding: 10px 12px;
  border-bottom: 1px solid rgba(31,41,55,.5);
  cursor: pointer;
}

.suggestion:last-child {
  border-bottom: none;
}

.suggestion span {
  font-size: 12px;
  color: #9ca3af;
}

.suggestion.active {
  background: rgba(163,230,53,.12);
}

.hint {
  margin: 0;
  color: #9ca3af;
  font-size: 12px;
}

